import {expansionArt,expansionBoard} from './expansion-ui.mjs';
import {patternArt,patternBoard} from './pattern-game-ui.mjs';
import {strategyArt,strategyBoard} from './strategy-game-ui.mjs';
import {advancedArt,advancedBoard} from './advanced-game-ui.mjs';
import {tutorialPanel,tutorialLink} from './tutorials.mjs';
import {moreArt,moreBoard} from './more-game-ui.mjs';
import {categories,games,roadmap,problemLabel,newRound,move,accepts} from './logic.mjs';
import {languages,getLanguage,getProvider,languageHelp} from './languages.mjs';
import {migrateProgress,draftFor,saveDraft,passedLanguage,solvedIn} from './coding-state.mjs';
import {createCodeEditor} from './vendor/editor.mjs';
import {runJavaScript,runRemote,REMOTE_TIMEOUT} from './execution.mjs';
const $=s=>document.querySelector(s), app=$('#app');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress={},filter='All games',current=null,state=null,transition=null,activeRun=null,editor=null,language='javascript';
try{const stored=JSON.parse(localStorage.getItem('algo-arcade-v1')||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored))progress=stored;}catch{}
migrateProgress(progress);
try{language=getLanguage(localStorage.getItem('algo-arcade-language-v1')).id;}catch{}
function save(){try{localStorage.setItem('algo-arcade-v1',JSON.stringify(progress));}catch{notify('Progress could not be saved in this browser session.');}stats();}
function notify(text){$('#notice').textContent=text;setTimeout(()=>$('#notice').textContent='',4500);}
function stats(){const xp=games.reduce((n,g)=>n+(progress[g.id]?.played?30:0)+(progress[g.id]?.solved?70:0),0);$('#xp').textContent=xp;$('#level').textContent=String(1+Math.floor(xp/100)).padStart(2,'0');}
function mark(id,key){progress[id]={...progress[id],[key]:true};save();}
function art(g){if(g.structures||g.expansion)return expansionArt(g);if(g.patterns)return patternArt(g);if(g.strategy)return strategyArt(g);if(g.advanced)return advancedArt(g);if(g.signature)return moreArt(g);return g.id==='brackets'?'<div class="bracket-art">{[ ]}</div>':`<div class="mini-array">${(g.id==='two-sum'?[2,'+',7]:[4,2,8,2]).map((n,i)=>`<span class="${n==='+'?'plus':(g.id==='two-sum'||i===1||i===3?'chosen':'')}">${n}</span>`).join('')}</div>`;}
function card(g){const done=progress[g.id]?.solved;return `<article class="game-card"><div class="card-art ${g.color}"><span class="art-badge">${done?'✓ COMPLETED':(g.difficulty||'Easy').toUpperCase()}</span>${art(g)}</div><div class="card-body"><div class="card-meta">${g.category.toUpperCase()} <span> / ${g.tag}</span></div><h3>${problemLabel(g)}</h3><p>${g.description}</p><div class="card-bottom"><span>◷ ${g.time} &nbsp; · &nbsp; +100 XP</span><a class="play-link" href="#play/${g.id}">${done?'Play again':'Play game'} <span>↗</span></a></div></div></article>`;}
function explore(){
 app.innerHTML=`<section class="intro"><h1>Big ideas start with a little play.</h1><p>Build your intuition. Find the pattern. Then make it code.</p></section>
 <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> YOUR NEXT “AHA!” MOMENT</div><h2>Play the pattern.<br><em>Own the algorithm.</em></h2><p>Turn tricky coding problems into hands-on games.<br>No blank editor. Just a good place to start.</p><a class="btn orange" href="#play/two-sum">Let’s play <span>↗</span></a><span class="quiet">Start with ${problemLabel(games[0])} · 5 min</span></div><div class="hero-art" aria-hidden="true"><div class="art-inner"><span class="spark">✳</span><span class="art-target">TARGET <b>9</b></span><div class="art-array"><div class="art-tile matched">2<small>0</small></div><div class="art-tile matched">7<small>1</small></div><div class="art-tile">11<small>2</small></div><div class="art-tile">15<small>3</small></div></div><div class="art-label"><span>✓</span> a perfect pair. a pattern unlocked.</div></div></div></section>
 <div class="steps-strip"><span><b>01</b> Play a little game</span><span class="arrow">→</span><span><b>02</b> Discover the pattern</span><span class="arrow">→</span><span><b>03</b> Write the code</span></div>
 <section aria-labelledby="library-title"><div class="section-heading"><h2 id="library-title">Pick your playground</h2><span class="source-tag">THE BLIND 75 COLLECTION ↗</span></div><div class="filters" role="group" aria-label="Filter by topic"><button class="filter ${filter==='All games'?'active':''}" data-filter="All games" aria-pressed="${filter==='All games'}">All games <span>${games.length}</span></button>${categories.map(([name,icon,count])=>`<button class="filter ${filter===name?'active':''}" data-filter="${name}" aria-pressed="${filter===name}">${name}<span>${count}</span></button>`).join('')}</div><div class="section-heading"><small>${filter==='All games'?'PLAYABLE NOW · EASY TO HARD':filter.toUpperCase()+' · LEARNING PATH'}</small><small>${filter==='All games'?games.length+' games ready to play':games.filter(g=>(g.category===filter||g.alsoCategories?.includes(filter))).length+' playable'}</small></div><div class="game-grid">${games.filter(g=>filter==='All games'||(g.category===filter||g.alsoCategories?.includes(filter))).map(card).join('')}</div>${filter!=='All games'?`<div class="roadmap">${(roadmap[filter]||[]).map(problem=>`<div class="roadmap-item"><div>${problemLabel(problem)}${tutorialLink(problem.number)}</div><span>Planned game</span></div>`).join('')}</div>`:''}<div class="bottom-note"><span>♧</span><div><strong>The complete Blind 75.</strong> All ${games.length} problems are playable, with visual games, coding exercises, and algorithm tutorials.</div><a href="#how">How it works ↗</a></div></section>`;
 app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{const scroll=app.querySelector('.filters').scrollLeft;filter=b.dataset.filter;explore();app.querySelector('.filters').scrollLeft=scroll;app.querySelector(`[data-filter="${filter}"]`)?.focus({preventScroll:true});});
}
function lessonHeading(g,phase){return `<button class="back" id="back">← Back to playground</button><div class="lesson-heading"><div><div class="eyebrow">${g.category.toUpperCase()} / LEETCODE #${g.number}</div><h1>${problemLabel(g)}</h1></div><div class="phase"><span class="${phase==='play'?'current':''}">${phase==='code'?'✓':'01'} Play the pattern</span>→<span class="${phase==='code'?'current':''}">02 Write the code</span></div></div>`;}
function renderGame(){renderGameContent();app.insertAdjacentHTML('beforeend',tutorialPanel(current.number));}
function renderGameContent(){
 if(current.signature){app.innerHTML=lessonHeading(current,'play')+(current.structures||current.expansion?expansionBoard(current,state):current.patterns?patternBoard(current,state):current.strategy?strategyBoard(current,state):current.advanced?advancedBoard(current,state):moreBoard(current,state));$('#back').onclick=()=>location.hash='';app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,Number(b.dataset.value)));app.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>act('match',Number(b.dataset.match)));return;}
 const g=current,r=g.rounds[state.round],value=r.values[state.index],two=g.id==='two-sum',duplicate=g.id==='duplicate';
 const instruction=two?`Find a pair that adds up to ${r.target}.`:duplicate?'Spot the repeat. Remember the rest.':'Give every opening bracket its match.';
 const guidance=two?`Current number: ${value}. Look for ${r.target} − ${value} = ${r.target-value} in your memory.`:duplicate?`Current number: ${value}. Is it already in your collection?`:`Read left to right. Only the top of the stack can match a closing bracket.`;
 app.innerHTML=lessonHeading(g,'play')+`<div class="game-layout"><section class="game-board"><div class="board-top"><span>ROUND ${state.round+1} OF ${g.rounds.length}</span><span class="target">${two?'TARGET <b>'+r.target+'</b>':duplicate?'SEEN IT BEFORE?':'LAST IN, FIRST OUT'}</span></div><h2 class="instruction">${instruction}</h2><p class="subtext">${state.done?'Round complete. Nice work!':guidance}</p><div class="tiles" aria-label="Input sequence">${r.values.map((v,i)=>`<div class="tile ${i===state.index&&!state.done?'current':i<state.index?'processed':''}">${v}<small>index ${i}</small></div>`).join('')}</div><div class="memory-label">${g.id==='brackets'?'YOUR STACK · TOP IS ON THE RIGHT':'YOUR MEMORY · SAVED VALUES'}</div><div class="memory">${state.memory.length?state.memory.map((m,i)=>two?`<button data-match="${i}" ${state.done?'disabled':''} aria-label="Match ${m.value} at index ${m.index}">${m.value}<small>idx ${m.index}</small></button>`:`<div class="memory-item">${m.value}${g.id==='brackets'&&i===state.memory.length-1?'<small>TOP</small>':''}</div>`).join(''):'<span>Nothing here yet. Start with the first item.</span>'}</div><div class="controls">${state.done?'':two?'<button class="btn" data-action="store">Save number & move →</button>':duplicate?'<button class="btn" data-action="store">New number · save →</button><button class="btn ghost" data-action="duplicate">I’ve seen this!</button>':'<button class="btn" data-action="push">Push opener ↓</button><button class="btn ghost" data-action="pop">Match & pop ↑</button><button class="btn ghost" data-action="reject">Reject sequence</button>'}</div><div id="game-feedback" aria-live="polite">${state.message?`<p class="feedback ${state.error?'error':''}">${state.message}${state.done?'<br><strong>'+(state.round+1===g.rounds.length?'Pattern unlocked. Opening your coding exercise…':'Loading the next round…')+'</strong>':''}</p>`:''}</div></section><aside class="explanation"><div class="icon">✳</div><h2>${g.concept}</h2><p>${two?'Don’t try every possible pair. Give your memory the hard work.':duplicate?'A collection of unique numbers is all you need to catch a repeat.':'Think of a stack of plates: the last one added is the first one removed.'}</p><ol>${(two?['Inspect the current number.','Look for its complement in memory.','No match? Save it and move on.']:duplicate?['Inspect one number at a time.','Check your collection.','Save a new number; flag a repeat.']:['Push every opening bracket.','Match closers with the top opener.','Reject a mismatch immediately.']).map(s=>`<li>${s}</li>`).join('')}</ol><div class="divider">No timer. No lost lives.<br>Experiment until it clicks.</div></aside></div>`;
 $('#back').onclick=()=>location.hash='';
 app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));
 app.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>act('match',Number(b.dataset.match)));
}
function act(action,index){state=move(current,state,action,index);renderGame();if(state.done){transition=setTimeout(()=>{transition=null;if(state.round+1<current.rounds.length){state=newRound(current,state.round+1);renderGame();}else{mark(current.id,'played');location.hash='code/'+current.id;}},1600);}}
function renderCode(){
 editor?.destroy();editor=null;
 const g=current,lang=getLanguage(language),help=languageHelp(g,language);
 app.innerHTML=lessonHeading(g,'code')+`<div class="code-layout"><section class="lesson-panel"><span class="earned">✓ GAME COMPLETE &nbsp; +30 XP</span><h2>You played it. Now build it.</h2><p>${g.prompt}</p><div class="concept"><strong>YOUR MOVES → YOUR ALGORITHM</strong><p>${escape(help.lesson)}</p></div><p><strong>Example input</strong><br><code>${escape(g.tests[0].args.map(a=>JSON.stringify(a)).join(', '))}</code><br><strong>Example output</strong><br><code>${g.id==='two-sum'?'[0, 1]':escape(JSON.stringify(g.tests[0].expected))}</code></p><details class="hint"><summary>A little nudge?</summary><p>${escape(help.hint)}</p></details><p><a class="play-link" href="#play/${g.id}">↶ Replay the game</a></p>${tutorialPanel(g.number)}</section><section class="coding-section"><div class="code-panel"><div class="editor-top"><span class="editor-filename">${lang.filename}</span><label class="language-picker" for="language">Language <select id="language">${languages.map(l=>`<option value="${l.id}" ${l.id===language?'selected':''}>${l.label}</option>`).join('')}</select></label></div><div class="editor-context"><span>${lang.runtime}</span><span>Draft saved per language</span></div><div id="editor"></div><p id="editor-help" class="editor-help">Tab to indent · Esc, then Tab to leave · Ctrl/⌘ + Enter to run</p><p class="signature-note">${escape(help.contract)}</p><div class="editor-bottom"><span>${g.tests.length} test cases</span><div class="run-controls"><button id="cancel-run" class="btn cancel-run" hidden>Cancel</button><button id="run" class="btn orange">Run tests <span>▷</span></button></div></div><p class="practice-note">${language==='javascript'?'JavaScript runs in your browser.':`Run tests sends your code to <a href="${getProvider(language).url}" target="_blank" rel="noreferrer">${getProvider(language).name} ↗</a> for compilation and execution. An internet connection is required.`} Tests check correctness, not complexity.</p><div id="results" class="test-results" role="status" aria-live="polite">Your next small win is a few lines away.</div></div><div id="completion"></div></section></div>`;
 $('#back').onclick=()=>location.hash='';
 editor=createCodeEditor({parent:$('#editor'),value:draftFor(progress[g.id],g,language),language,label:lang.label+' solution',onChange:value=>{progress[g.id]=saveDraft(progress[g.id],language,value);save();},onRun:runTests});
 $('#language').onchange=event=>{
   stopRunner();language=getLanguage(event.target.value).id;
   try{localStorage.setItem('algo-arcade-language-v1',language);}catch{}
   renderCode();$('#language').focus({preventScroll:true});
 };
 $('#run').onclick=runTests;
 $('#cancel-run').onclick=()=>{stopRunner();setRunning(false);$('#results').textContent='Run cancelled. Your draft is saved.';};
 if(progress[g.id]?.solvedLanguages?.[language])showCompletion();
 editor.focus();
}
function stopRunner(){const run=activeRun;activeRun=null;if(run){clearTimeout(run.timer);run.controller.abort();}}
function setRunning(running){$('#run').disabled=running;$('#run').textContent=running?'Running…':'Run tests ▷';$('#cancel-run').hidden=!running;editor.setReadOnly(running);}
async function runTests(){
 if(activeRun)return;
 const g=current,runLanguage=language,code=editor.getValue(),results=$('#results');
 progress[g.id]=saveDraft(progress[g.id],runLanguage,code);save();
 const run={controller:new AbortController(),timer:null,timedOut:false};activeRun=run;
 setRunning(true);$('#completion').innerHTML='';results.textContent=runLanguage==='javascript'?'Checking your solution…':`Compiling and running ${getLanguage(runLanguage).label} on ${getProvider(runLanguage).name}… This may take a few seconds.`;
 if(runLanguage!=='javascript')run.timer=setTimeout(()=>{run.timedOut=true;run.controller.abort();},REMOTE_TIMEOUT);
 try{
   const data=await (runLanguage==='javascript'?runJavaScript(g,code,run.controller.signal):runRemote(g,runLanguage,code,run.controller.signal));
   if(activeRun!==run)return;
   if(data?.error){results.textContent=data.error;return;}
   if(!Array.isArray(data?.results)||data.results.length!==g.tests.length||data.results.some(r=>!r||typeof r!=='object')){results.textContent='The runner did not return every test result. Please try again.';return;}
   let passed=0;
   results.innerHTML=data.results.map((r,i)=>{const test=g.tests[i];const ok=!r.error&&accepts(g,test,r.value);if(ok)passed++;return `<div class="test-row ${ok?'passed':'failed'}">${ok?'✓':'×'} Test ${i+1} · ${ok?'Passed':'Try again'}<code>Input: ${escape(test.args.map(x=>JSON.stringify(x)).join(', '))}<br>${r.error?'Error: '+escape(r.error):'Returned: '+escape(JSON.stringify(r.value)??'undefined')}${ok?'':'<br>Expected: '+(g.id==='two-sum'?'two distinct indices whose values add to the target':escape(JSON.stringify(test.expected)))}</code></div>`;}).join('');
   if(data.diagnostics)results.insertAdjacentHTML('beforeend',`<details class="compiler-details"><summary>Compiler notes</summary><pre>${escape(data.diagnostics)}</pre></details>`);
   if(passed===g.tests.length){progress[g.id]=passedLanguage(progress[g.id],runLanguage);save();showCompletion();}
   else results.insertAdjacentHTML('afterbegin',`<div class="all-clear">${passed}/${g.tests.length} passed. Keep going—you’re close.</div>`);
 }catch(error){
   if(activeRun!==run)return;
   results.textContent=run.timedOut?'The compiler did not finish within 45 seconds. Check for an infinite loop, or try again if the service is busy. Your draft is saved.':error.name==='AbortError'?'Run cancelled. Your draft is saved.':error instanceof TypeError?'Could not reach the compiler service. Check your connection and try again. Your draft is saved.':error.message;
 }finally{
   clearTimeout(run.timer);
   if(activeRun===run){activeRun=null;setRunning(false);}
 }
}
function showCompletion(){const next=games.find(g=>g.id!==current.id&&!progress[g.id]?.solved);$('#completion').innerHTML=`<div class="completion"><div><h3>Pattern mastered. Nicely done.</h3><p>${getLanguage(language).label} tests passed · 100 XP per challenge, earned once</p></div><a class="btn" href="${next?'#play/'+next.id:'#progress'}">${next?'Next game →':'View progress →'}</a></div>`;}
function renderProgress(){const played=games.filter(g=>progress[g.id]?.played).length,solved=games.filter(g=>progress[g.id]?.solved).length;app.innerHTML=`<section class="intro"><div class="eyebrow">YOUR LEARNING ADVENTURE</div><h1 style="margin-top:12px">Small wins add up.</h1><p>Every pattern you understand is another tool in your toolkit.</p></section><div class="progress-grid"><div class="stat-card"><div class="number">${played}<span style="font-size:18px;color:#a1a894"> / ${games.length}</span></div><p>Games completed</p></div><div class="stat-card"><div class="number">${solved}<span style="font-size:18px;color:#a1a894"> / ${games.length}</span></div><p>Code challenges passed</p></div><div class="stat-card"><div class="number">${played*30+solved*70}</div><p>Experience points earned</p></div></div>${games.map(g=>`<div class="progress-row"><div><h3>${problemLabel(g)}</h3><p>${progress[g.id]?.solved?'✓ Code passed in '+solvedIn(progress[g.id]).join(', '):progress[g.id]?.played?'✓ Game complete · Coding exercise ready':'Your next “aha!” is waiting'}</p></div><a class="btn ${progress[g.id]?.solved?'ghost':''}" href="#${progress[g.id]?.played?'code':'play'}/${g.id}">${progress[g.id]?.solved?'Review code':progress[g.id]?.played?'Continue coding':'Start playing'} ↗</a></div>`).join('')}<p class="subtext" style="margin-top:20px">Progress and code drafts are saved on this browser. XP is earned once per challenge.</p>`;}
function renderHow(){app.innerHTML=`<section class="intro"><div class="eyebrow">LEARN BY DOING</div><h1 style="margin-top:12px">The game is the explanation.</h1><p>Learn an algorithm with your hands before you write it with your keyboard.</p></section><div class="how-grid"><article class="how-card"><span>01</span><h2>Play the pattern.</h2><p>Move through a small visual challenge. Save a number, spot a repeat, or match a bracket. Mistakes give you feedback, not a penalty.</p></article><article class="how-card"><span>02</span><h2>Make the connection.</h2><p>Finish two rounds and jump straight into the coding exercise. Connect your moves to the code: maps, stacks, two pointers, dynamic programming, graph traversal, sliding windows, linked lists, trees, tries, and heaps.</p></article><article class="how-card"><span>03</span><h2>Make it your own.</h2><p>Choose JavaScript, C, C++, Java, Rust, Go, or Python and run the practice tests. Get feedback, refine your approach, and earn XP when every test passes.</p></article></div><div class="bottom-note"><span>✳</span><div>All ${games.length} Blind 75 problems are playable, from Easy to Hard. Explore all 10 topic groups. Merge k Sorted Lists appears in Linked List and Heap, with shared progress.</div></div><a href="#play/two-sum" class="btn orange" style="margin-top:25px">Try your first game ↗</a>`;}
function route(){editor?.destroy();editor=null;clearTimeout(transition);transition=null;stopRunner();const [page,id]=location.hash.slice(1).split('/');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(page==='progress'||page==='how'?page:'explore')));$('#breadcrumb').innerHTML='The playground <span>/ '+(page==='play'?'Play':page==='code'?'Code':page==='progress'?'Progress':page==='how'?'How it works':'Explore')+'</span>';
 if(page==='play'||page==='code'){current=games.find(g=>g.id===id);if(!current){location.hash='';return;}if(page==='code'&&!progress[id]?.played){location.replace('#play/'+id);return;}if(page==='play'){state=newRound(current);renderGame();}else renderCode();}
 else if(page==='progress')renderProgress();else if(page==='how')renderHow();else explore();
 window.scrollTo({top:0,behavior:'instant'});stats();
}
window.addEventListener('hashchange',route);route();
